func instance(path: String) -> Node3D:
	if not _scenes.has(path):
		_scenes[path] = load(path)
	var model: Node3D = _scenes[path].instantiate()
	_repair(model)
	var holder := Node3D.new()
	holder.name = path.get_file().get_basename()
	for pack in Z_UP_PACKS:
		if path.contains(pack):
			model.rotation_degrees.x = -90.0
	holder.add_child(model)
	return holder

func _unhandled_input(event: InputEvent) -> void:
	if not world.can_look():
		return
	if event is InputEventMouseMotion and Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
		_look(event.relative * LOOK_SCALE * GameState.mouse_sensitivity)

func _look(amount: Vector2) -> void:
	rotation.y -= amount.x
	x_rotation = clampf(x_rotation - amount.y, deg_to_rad(-89.0), deg_to_rad(89.0))
	camera.rotation.x = x_rotation

# SelectionManager.Update: only interactables within reach are selectable.
func _update_selection() -> void:
	target = null
	if not world.can_look():
		world.hud.set_interaction("")
		return
	ray.force_raycast_update()
	if ray.is_colliding():
		var collider := ray.get_collider()
		if collider and collider.has_method("get_prompt"):
			target = collider
	world.hud.set_interaction(target.get_prompt(self) if target else "")

var can_craft := true
for requirement in blueprint[3]:
	var owned: int = world.inventory.count(requirement[0])
	var enough: bool = owned >= requirement[1]
	can_craft = can_craft and enough
	text_column.add_child(GameState.make_label("%d %s [%d]" % [requirement[1], requirement[0], owned], 16, GameState.MOSS if enough else Color("e8a598")))
if blueprint[2]:
	var near: bool = world.near_campfire()
	can_craft = can_craft and near
	text_column.add_child(GameState.make_label("Needs a campfire nearby" if not near else "Campfire nearby", 14, GameState.MOSS if near else Color("e8a598")))
var craft := GameState.make_button("Craft", func(): _craft(blueprint), Vector2(150, 54))
craft.size_flags_vertical = Control.SIZE_SHRINK_CENTER
craft.visible = can_craft
line.add_child(craft)

func _refresh_objectives() -> void:
	var sticks: int = inventory.count("Stick")
	var gold: int = inventory.count("Gold")
	var logs: int = inventory.count("Log")
	var stones: int = inventory.count("Stone")
	var steps := [
		["Gather 3 Sticks  (%d/3)" % mini(sticks, 3), axe_crafted or sticks >= 3],
		["Gather 3 Gold nuggets  (%d/3)" % mini(gold, 3), axe_crafted or gold >= 3],
		["Craft an Axe  [C]", axe_crafted],
		["Chop trees for 4 Logs  (%d/4)" % mini(logs, 4), campfire_crafted or logs >= 4],
		["Collect 3 Stones  (%d/3)" % mini(stones, 3), campfire_crafted or stones >= 3],
		["Craft and place a Campfire before dark", campfire_placed],
		["Survive the night beside the fire", survived_night]
	]
	hud.set_objectives(steps)

func chop(from: Vector3) -> bool:
	if falling:
		return false
	hits_left -= 1
	var shake := create_tween()
	shake.tween_property(model, "rotation:z", 0.04, 0.05)
	shake.tween_property(model, "rotation:z", -0.03, 0.06)
	shake.tween_property(model, "rotation:z", 0.0, 0.06)
	if hits_left <= 0:
		_fall(from)
	return true

func _physics_process(delta: float) -> void:
	if dead:
		return
	var to_player := global_position - player.global_position
	to_player.y = 0.0
	fleeing = to_player.length() < FLEE_RADIUS
	if fleeing:
		var away := to_player.normalized()
		rotation.y = atan2(away.x, away.z)
		_move(away * FLEE_SPEED * delta)
		_play("Run")
		return

func _place_campfire(at := Vector3.INF) -> bool:
	if at == Vector3.INF:
		var forward := -player.global_transform.basis.z
		forward.y = 0.0
		var spot := player.global_position + forward.normalized() * 2.6
		at = _ground(spot.x, spot.z)
		if at.y < WATER_LEVEL + 0.2:
			hud.show_message("You can't build a fire in the water")
			return false

func _can_drop_data(_at_position: Vector2, data: Variant) -> bool:
	return data is Dictionary and data.has("inventory_slot")

func _drop_data(_at_position: Vector2, data: Variant) -> void:
	inventory.move_item(data["inventory_slot"], index)

func _gui_input(event: InputEvent) -> void:
	if event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_RIGHT:
		inventory.use_item(index)
		accept_event()

func _update_time(delta: float) -> void:
	var seconds_per_hour := NIGHT_SECONDS_PER_HOUR if is_night() else DAY_SECONDS_PER_HOUR
	var was_night := is_night()
	hour += delta / seconds_per_hour * (REST_SPEED if resting else 1.0)
	if hour >= 24.0:
		hour -= 24.0
		day += 1
	if is_night() and near_campfire():
		night_with_fire = true
	if was_night and not is_night():
		resting = false
		if campfire_placed and night_with_fire and stats.alive:
			survived_night = true
			_victory()
			return
		night_with_fire = false
	if was_night != is_night() and not was_night:
		hud.show_message("Night falls. Stay by your fire.", 3.5)

if current_calories <= 0.0 or current_hydration <= 0.0:
	damage_timer += delta
	if damage_timer >= 1.0:
		damage_timer = 0.0
		_damage(STARVE_DAMAGE, "You starved" if current_calories <= 0.0 else "You died of thirst")
freezing = cold
if cold:
	cold_timer += delta
	if cold_timer >= COLD_INTERVAL:
		cold_timer = 0.0
		_damage(COLD_DAMAGE, "You froze in the night")

func save_game() -> bool:
	var fires := []
	for fire in campfires:
		fires.append([fire.global_position.x, fire.global_position.y, fire.global_position.z])
	var apples := {}
	for id in entities:
		if entities[id].get_script() == FruitTreeScript:
			apples[id] = entities[id].apples
	var data := {
		"version": 1,
		"day": day, "hour": hour, "play_time": play_time,
		"player": [player.global_position.x, player.global_position.y, player.global_position.z, player.rotation.y, player.look_pitch()],
		"stats": stats.to_dict(),
		"inventory": inventory.slots,
		"equipped": player.equipped,
		"flags": {"axe": axe_crafted, "campfire_crafted": campfire_crafted, "campfire_placed": campfire_placed, "night_with_fire": night_with_fire},
		"counters": {"items": items_gathered, "trees": trees_felled, "rabbits": rabbits_hunted, "dynamic": dynamic_counter},
		"removed": removed_ids.keys(),
		"dynamic": dynamic_pickups,
		"campfires": fires,
		"apples": apples
	}
	return GameState.write_save(data)
